package com.vahotel.web;
import com.vahotel.model.*;import com.vahotel.repo.*;import jakarta.servlet.http.HttpServletResponse;import java.io.IOException;import java.nio.file.*;import java.math.BigDecimal;import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class ManagementController {private final AccountRepository accounts;private final RoomRepository rooms;private final ReservationRepository reservations;private final PaymentRecordRepository payments;private final CustomerReportRepository reports;private final org.springframework.security.crypto.password.PasswordEncoder encoder;private final com.vahotel.service.ReservationService reservationService;private final com.vahotel.service.PaymentService paymentService;private final com.vahotel.service.EmailNotificationService email;private final com.vahotel.service.DecisionLogService decisionLogs;
 public ManagementController(AccountRepository a,RoomRepository r,ReservationRepository b,PaymentRecordRepository p,CustomerReportRepository c,org.springframework.security.crypto.password.PasswordEncoder e,com.vahotel.service.ReservationService rs,com.vahotel.service.PaymentService ps,com.vahotel.service.EmailNotificationService email,com.vahotel.service.DecisionLogService decisionLogs){accounts=a;rooms=r;reservations=b;payments=p;reports=c;encoder=e;reservationService=rs;paymentService=ps;this.email=email;this.decisionLogs=decisionLogs;}
 @GetMapping({"/super-admin/dashboard","/online-manager/dashboard","/onsite-manager/dashboard"}) public String dashboard(Model m,org.springframework.security.core.Authentication authentication,jakarta.servlet.http.HttpServletRequest request){String path=request.getServletPath();boolean superAdminPortal=path.startsWith("/super-admin/");boolean onlinePortal=path.startsWith("/online-manager/");boolean onsitePortal=path.startsWith("/onsite-manager/");long reservationsNeedingAttention=reservations.findAll().stream().filter(r->"PENDING".equals(r.getStatus())||"PAID".equals(r.getStatus())||"CANCELLATION_REQUESTED".equals(r.getStatus())).count();m.addAttribute("pendingReservations",reservationsNeedingAttention);m.addAttribute("activeRooms",rooms.findByActiveTrue().size());m.addAttribute("isSuperAdmin",superAdminPortal);m.addAttribute("isOnlineManager",onlinePortal);m.addAttribute("isOnsiteManager",onsitePortal);if(superAdminPortal){var pending=accounts.findAll().stream().filter(a->a.getRole()==Role.CUSTOMER&&!a.isEnabled()).toList();m.addAttribute("pendingCustomers",pending.size());m.addAttribute("reviewAccounts",pending.stream().limit(6).toList());}else{m.addAttribute("pendingCustomers",0);m.addAttribute("reviewAccounts",java.util.List.of());}m.addAttribute("today",java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")));return "management";}
 @GetMapping("/management/decisions") public String decisions(Model m){m.addAttribute("decisions",decisionLogs.recent());return "decision-history";}
 @GetMapping("/management/customers") public String customers(Model m){m.addAttribute("accounts",accounts.findAll().stream().filter(a->a.getRole()==Role.CUSTOMER).toList());return "customers";}
 @PostMapping("/management/customers/{id}/approve") public String approve(@PathVariable Long id,RedirectAttributes f,org.springframework.security.core.Authentication actor){Account a=accounts.findById(id).orElseThrow();if(a.getRole()!=Role.CUSTOMER||!a.isEmailVerified()||a.getIdentityDocumentPath()==null){f.addFlashAttribute("error","Approval requires a verified email and an identity document.");return "redirect:/management/customers";}a.setEnabled(true);accounts.save(a);email.sendRegistrationApproved(a);decisionLogs.record(actor,"Approved customer registration",a.getEmail(),a.getFullName());f.addFlashAttribute("message","Customer account approved.");return "redirect:/management/customers";}
 @PostMapping("/management/customers/{id}/reject") public String reject(@PathVariable Long id,RedirectAttributes f,org.springframework.security.core.Authentication actor){Account a=accounts.findById(id).orElseThrow();if(a.getRole()!=Role.CUSTOMER){f.addFlashAttribute("error","Only customer registrations can be rejected here.");return "redirect:/management/customers";}String emailAddress=a.getEmail(),name=a.getFullName();accounts.delete(a);email.sendRegistrationRejected(name,emailAddress);decisionLogs.record(actor,"Rejected customer registration",emailAddress,name);f.addFlashAttribute("message","Customer registration rejected.");return "redirect:/management/customers";}
 @GetMapping("/management/customers/{id}/identity") public ResponseEntity<Resource> identity(@PathVariable Long id){Account a=accounts.findById(id).orElseThrow();if(a.getIdentityDocumentPath()==null)return ResponseEntity.notFound().build();Path p=Path.of(a.getIdentityDocumentPath()).toAbsolutePath().normalize();if(!Files.exists(p))return ResponseEntity.notFound().build();Resource res=new FileSystemResource(p);return ResponseEntity.ok().contentType(MediaType.APPLICATION_OCTET_STREAM).header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename=identity-"+id).body(res);}
 @org.springframework.beans.factory.annotation.Value("${va.hotel.room-image.storage:./data/room-images}") private String roomImageStorage;
 @GetMapping("/management/rooms") public String roomList(Model m){m.addAttribute("rooms",rooms.findAll().stream().sorted(java.util.Comparator.comparing(Room::getRoomNumber)).toList());return "manage-rooms";}
 @PostMapping("/management/rooms") public String addRoom(@RequestParam String roomNumber,@RequestParam String roomType,@RequestParam String description,@RequestParam BigDecimal nightlyPrice,@RequestParam(required=false) org.springframework.web.multipart.MultipartFile photo,RedirectAttributes f){try{String number=roomNumber.trim();if(number.isEmpty()||roomType.isBlank()||description.isBlank()||nightlyPrice.signum()<=0)throw new IllegalArgumentException("Enter a room number, type, description, and positive nightly price.");if(rooms.findByRoomNumber(number).isPresent())throw new IllegalArgumentException("That room number already exists.");Room room=new Room(number,roomType.trim(),description.trim(),nightlyPrice);String saved=saveRoomPhoto(photo);if(saved!=null)room.setPhotoPath(saved);rooms.save(room);f.addFlashAttribute("message","Room added.");}catch(Exception e){f.addFlashAttribute("error",safeError(e,"Unable to add the room."));}return "redirect:/management/rooms";}
 @PostMapping("/management/rooms/{id}/update") public String updateRoom(@PathVariable Long id,@RequestParam String roomNumber,@RequestParam String roomType,@RequestParam String description,@RequestParam BigDecimal nightlyPrice,@RequestParam(required=false) org.springframework.web.multipart.MultipartFile photo,RedirectAttributes f){try{Room room=rooms.findById(id).orElseThrow();String number=roomNumber.trim();if(number.isEmpty()||roomType.isBlank()||description.isBlank()||nightlyPrice.signum()<=0)throw new IllegalArgumentException("Enter a room number, type, description, and positive nightly price.");var duplicate=rooms.findByRoomNumber(number);if(duplicate.isPresent()&&!duplicate.get().getId().equals(id))throw new IllegalArgumentException("That room number already exists.");String oldPhoto=room.getPhotoPath();room.setDescription(description.trim());room.setRoomType(roomType.trim());room.setRoomNumber(number);room.setNightlyPrice(nightlyPrice);String saved=saveRoomPhoto(photo);if(saved!=null)room.setPhotoPath(saved);rooms.save(room);if(saved!=null)deleteRoomPhoto(oldPhoto);f.addFlashAttribute("message","Room details updated.");}catch(Exception e){f.addFlashAttribute("error",safeError(e,"Unable to update the room."));}return "redirect:/management/rooms";}
 @PostMapping("/management/rooms/{id}/delete") public String deleteRoom(@PathVariable Long id,RedirectAttributes f,org.springframework.security.core.Authentication actor){Room room=rooms.findById(id).orElseThrow();if(reservations.existsByRoom_Id(id)){f.addFlashAttribute("error","This room has reservation history and cannot be deleted. Archive it by marking it inactive instead.");return "redirect:/management/rooms";}String roomNumber=room.getRoomNumber();String oldPhoto=room.getPhotoPath();rooms.delete(room);deleteRoomPhoto(oldPhoto);decisionLogs.record(actor,"Deleted room","Room "+roomNumber,"Removed room listing");f.addFlashAttribute("message","Room deleted.");return "redirect:/management/rooms";}
 @PostMapping("/management/rooms/{id}/toggle") public String toggle(@PathVariable Long id,org.springframework.security.core.Authentication actor){Room r=rooms.findById(id).orElseThrow();r.setActive(!r.isActive());rooms.save(r);decisionLogs.record(actor,r.isActive()?"Restored room":"Archived room","Room "+r.getRoomNumber(),"Guest availability: "+r.isActive());return "redirect:/management/rooms";}
 @GetMapping("/room-photos/{id}") public ResponseEntity<Resource> roomPhoto(@PathVariable Long id)throws IOException{Room room=rooms.findById(id).orElse(null);if(room==null||room.getPhotoPath()==null)return ResponseEntity.notFound().build();String filename=room.getPhotoPath();if(!filename.matches("[a-fA-F0-9-]+\\.(jpg|png)"))return ResponseEntity.notFound().build();Path directory=Path.of(roomImageStorage).toAbsolutePath().normalize();Path image=directory.resolve(filename).normalize();if(!image.startsWith(directory)||!Files.isRegularFile(image))return ResponseEntity.notFound().build();MediaType type=filename.endsWith(".png")?MediaType.IMAGE_PNG:MediaType.IMAGE_JPEG;return ResponseEntity.ok().contentType(type).cacheControl(CacheControl.noCache()).body(new FileSystemResource(image));}
 private String saveRoomPhoto(org.springframework.web.multipart.MultipartFile photo)throws IOException{if(photo==null||photo.isEmpty())return null;if(photo.getSize()>5*1024*1024)throw new IllegalArgumentException("Room photos must be 5 MB or smaller.");String type=photo.getContentType();if(!"image/jpeg".equals(type)&&!"image/png".equals(type))throw new IllegalArgumentException("Upload a JPG or PNG room photo.");byte[] bytes=photo.getBytes();java.awt.image.BufferedImage decoded=javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(bytes));if(decoded==null||decoded.getWidth()>8000||decoded.getHeight()>8000)throw new IllegalArgumentException("The uploaded file is not a supported room image.");Path directory=Path.of(roomImageStorage).toAbsolutePath().normalize();Files.createDirectories(directory);String filename=java.util.UUID.randomUUID()+("image/png".equals(type)?".png":".jpg");Files.write(directory.resolve(filename),bytes,StandardOpenOption.CREATE_NEW);return filename;}
 private void deleteRoomPhoto(String filename){if(filename==null||!filename.matches("[a-fA-F0-9-]+\\.(jpg|png)"))return;try{Path dir=Path.of(roomImageStorage).toAbsolutePath().normalize();Path image=dir.resolve(filename).normalize();if(image.startsWith(dir))Files.deleteIfExists(image);}catch(IOException ignored){}}
 private String safeError(Exception e,String fallback){return e instanceof IllegalArgumentException&&e.getMessage()!=null?e.getMessage():fallback;}
 @GetMapping("/management/reservations") public String reservationList(Model m){m.addAttribute("reservations",reservations.findAll());return "manage-reservations";}
 @PostMapping("/management/reservations/{id}/{decision}") public String decide(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f,org.springframework.security.core.Authentication actor){Reservation r=reservations.findById(id).orElseThrow();String previousStatus=r.getStatus();if("cancel".equals(decision)&&!"CANCELLATION_REQUESTED".equals(r.getStatus())){f.addFlashAttribute("error","There is no pending cancellation request for this reservation.");return "redirect:/management/reservations";}if("reject".equals(decision)&&"CANCELLATION_REQUESTED".equals(r.getStatus())){f.addFlashAttribute("error","Choose Keep reservation or Confirm cancellation for a cancellation request.");return "redirect:/management/reservations";}if("approve".equals(decision)&&!"PAID".equals(r.getStatus())&&!"PENDING".equals(r.getStatus())&&!"CANCELLATION_REQUESTED".equals(r.getStatus())){f.addFlashAttribute("error","Only fully paid reservations can be approved.");return "redirect:/management/reservations";}if(decision.equals("approve")){if("CANCELLATION_REQUESTED".equals(r.getStatus())){String restore=r.getStatusBeforeCancellation()==null?"APPROVED":r.getStatusBeforeCancellation();if(!r.getCheckIn().isAfter(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila"))))restore="EXPIRED";r.setStatus(restore);r.setStatusBeforeCancellation(null);}else{if(!r.getCheckIn().isAfter(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")))){f.addFlashAttribute("error","The reservation has expired because check-in has arrived.");return "redirect:/management/reservations";}r.setStatus("APPROVED");}}else if(decision.equals("reject"))r.setStatus("REJECTED");else if(decision.equals("cancel")){r.setStatus("CANCELLED");r.setStatusBeforeCancellation(null);}reservations.save(r);String update="approve".equals(decision)?("CANCELLATION_REQUESTED".equals(previousStatus)?"Your cancellation request was declined; the reservation has been restored to "+r.getStatus()+".":"Your reservation was approved."):"reject".equals(decision)?"Your reservation request was rejected.":"Your cancellation was confirmed.";email.sendReservationUpdate(r,update);decisionLogs.record(actor,update,"Reservation #"+id,"Room "+r.getRoom().getRoomNumber()+", "+r.getCheckIn()+" to "+r.getCheckOut()+"; status: "+r.getStatus());return "redirect:/management/reservations";}
 @GetMapping("/management/payments") public String paymentList(Model m){m.addAttribute("payments",payments.findAll());return "payments";}
 @GetMapping("/management/reports.csv") public void csv(HttpServletResponse res)throws IOException{res.setContentType("text/csv");res.setHeader("Content-Disposition","attachment; filename=va-hotel-reservations.csv");var w=res.getWriter();w.println("Reservation ID,Status,Check In,Check Out,Total Price,Amount Paid");for(Reservation r:reservations.findAll())w.printf("%d,%s,%s,%s,%s,%s%n",r.getId(),r.getStatus(),r.getCheckIn(),r.getCheckOut(),r.getTotalPrice(),r.getAmountPaid());}

 @GetMapping("/management/managers") public String managers(Model m){m.addAttribute("accounts",accounts.findAll().stream().filter(a->a.getRole()==Role.ONLINE_MANAGER||a.getRole()==Role.ONSITE_MANAGER).toList());return "managers";}
 @PostMapping("/management/managers") public String createManager(@RequestParam String fullName,@RequestParam String email,@RequestParam String role,@RequestParam String password,RedirectAttributes f){try{Role r=Role.valueOf(role);if(r!=Role.ONLINE_MANAGER&&r!=Role.ONSITE_MANAGER)throw new IllegalArgumentException("Invalid manager role.");if(accounts.findByEmail(email.trim().toLowerCase()).isPresent())throw new IllegalArgumentException("Email already exists.");if(password.length()<12)throw new IllegalArgumentException("Manager password must be at least 12 characters.");accounts.save(new Account(email.trim().toLowerCase(),encoder.encode(password),fullName.trim(),r,true));}catch(Exception e){f.addFlashAttribute("error",e.getMessage()==null?"Invalid manager details.":e.getMessage());}return "redirect:/management/managers";}
 @PostMapping("/management/managers/{id}/disable") public String disableManager(@PathVariable Long id,org.springframework.security.core.Authentication actor){Account a=accounts.findById(id).orElseThrow();if(a.getRole()==Role.ONLINE_MANAGER||a.getRole()==Role.ONSITE_MANAGER){a.setEnabled(false);accounts.save(a);decisionLogs.record(actor,"Disabled manager account",a.getEmail(),a.getFullName()+" ("+a.getRole()+")");}return "redirect:/management/managers";}
 @GetMapping("/management/walkins") public String walkins(Model m){m.addAttribute("rooms",rooms.findByActiveTrue());return "walkins";}
 @PostMapping("/management/walkins") public String createWalkin(@RequestParam String guestName,@RequestParam String guestEmail,@RequestParam Long roomId,@RequestParam java.time.LocalDate checkIn,@RequestParam java.time.LocalDate checkOut,@RequestParam String paymentMethod,RedirectAttributes f){try{String emailAddress=guestEmail.trim().toLowerCase();Account guest=accounts.findByEmail(emailAddress).orElseGet(()->accounts.save(new Account(emailAddress,encoder.encode(java.util.UUID.randomUUID().toString()),guestName.trim(),Role.CUSTOMER,true)));if(guest.getRole()!=Role.CUSTOMER)throw new IllegalArgumentException("That email belongs to a staff account.");Room room=rooms.findById(roomId).orElseThrow();Reservation booking=reservationService.create(guest,room,checkIn,checkOut);PaymentRecord walkInPayment=paymentService.simulateWalkInPayment(booking.getId(),booking.getTotalPrice(),paymentMethod);booking.setStatus("APPROVED");reservations.save(booking);boolean confirmationSent=email.sendReservationConfirmation(booking);boolean receiptSent=email.sendPaymentProof(walkInPayment);f.addFlashAttribute("message","Walk-in reservation created and full payment recorded as a simulation."+(confirmationSent&&receiptSent?" Confirmation and receipt were emailed to the guest.":" "+email.deliveryFailureMessage()));}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/management/walkins";}
 @GetMapping("/management/reports") public String reports(Model m,@RequestParam(defaultValue="month") String period){m.addAttribute("reports",reports.findAll());if(!java.util.Set.of("day","week","month","year").contains(period))period="month";var today=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila"));int periods=switch(period){case "day"->7;case "week"->12;case "year"->5;default->12;};java.time.LocalDate anchor=switch(period){case "week"->today.with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY));case "month"->today.withDayOfMonth(1);case "year"->today.withDayOfYear(1);default->today;};var grouped=new java.util.TreeMap<java.time.LocalDate,BigDecimal>();for(int i=periods-1;i>=0;i--){var bucket=switch(period){case "week"->anchor.minusWeeks(i);case "month"->anchor.minusMonths(i);case "year"->anchor.minusYears(i);default->anchor.minusDays(i);};grouped.put(bucket,BigDecimal.ZERO);}long filteredPayments=0;for(PaymentRecord p:payments.findAll()){if(p.getCreatedAt()==null)continue;var date=p.getCreatedAt().toLocalDate();var bucket=switch(period){case "week"->date.with(java.time.temporal.TemporalAdjusters.previousOrSame(java.time.DayOfWeek.MONDAY));case "month"->date.withDayOfMonth(1);case "year"->date.withDayOfYear(1);default->date;};if(!grouped.containsKey(bucket))continue;BigDecimal refund=p.getRefundAmount()==null?BigDecimal.ZERO:p.getRefundAmount();BigDecimal net=p.getAmount().subtract(refund).max(BigDecimal.ZERO);grouped.merge(bucket,net,BigDecimal::add);filteredPayments++;}BigDecimal peak=grouped.values().stream().max(BigDecimal::compareTo).orElse(BigDecimal.ZERO);BigDecimal total=grouped.values().stream().reduce(BigDecimal.ZERO,BigDecimal::add);var chart=new java.util.ArrayList<java.util.Map<String,Object>>();String chartPeriod=period;var formatter=java.time.format.DateTimeFormatter.ofPattern(period.equals("day")?"EEE, MMM d":"MMM d",java.util.Locale.ENGLISH);grouped.forEach((date,amount)->{int height=peak.signum()==0?0:amount.multiply(BigDecimal.valueOf(100)).divide(peak,0,java.math.RoundingMode.HALF_UP).intValue();String label=switch(chartPeriod){case "week"->"Week of "+date.format(formatter);case "month"->date.format(java.time.format.DateTimeFormatter.ofPattern("MMM yyyy",java.util.Locale.ENGLISH));case "year"->Integer.toString(date.getYear());default->date.format(formatter);};var point=new java.util.LinkedHashMap<String,Object>();point.put("label",label);point.put("amount",amount);point.put("height",height);chart.add(point);});String range=switch(period){case "day"->"Last 7 days";case "week"->"Last 12 weeks";case "year"->"Last 5 years";default->"Last 12 months";};m.addAttribute("revenueChart",chart);m.addAttribute("chartColumns",chart.size());m.addAttribute("revenueTotal",total);m.addAttribute("paymentCount",filteredPayments);m.addAttribute("period",period);m.addAttribute("periodRange",range);return "manager-reports";}
 @PostMapping("/management/reports/{id}/reply") public String reply(@PathVariable Long id,@RequestParam String reply,org.springframework.security.core.Authentication actor){CustomerReport report=reports.findById(id).orElseThrow();report.setManagerReply(reply);report.setStatus("RESOLVED");reports.save(report);email.sendCustomerReportReply(report);decisionLogs.record(actor,"Resolved customer message","Message #"+id,report.getSubject());return "redirect:/management/reports";}
 @GetMapping("/management/history") public String history(Model m,org.springframework.security.core.Authentication authentication){m.addAttribute("reservations",reservations.findAll());m.addAttribute("canManageStay",authentication.getAuthorities().stream().anyMatch(a->a.getAuthority().equals("ROLE_ONSITE_MANAGER")||a.getAuthority().equals("ROLE_SUPER_ADMIN")));return "reservation-history-manager";}


 @PostMapping("/management/payments/{id}/refund") public String refund(@PathVariable Long id,@RequestParam BigDecimal amount,RedirectAttributes f,org.springframework.security.core.Authentication actor){try{PaymentRecord refunded=paymentService.simulateRefund(id,amount);email.sendRefundProof(refunded);decisionLogs.record(actor,"Recorded simulated refund","Reservation #"+refunded.getReservation().getId(),"Refund amount: PHP "+amount+"; payment reference: "+refunded.getRefundReferenceCode());f.addFlashAttribute("message","Refund simulation recorded. No real money was transferred.");}catch(Exception e){f.addFlashAttribute("error",e.getMessage());}return "redirect:/management/payments";}
 @GetMapping("/management/revenue.csv") public void revenueCsv(HttpServletResponse res)throws IOException{res.setContentType("text/csv");res.setHeader("Content-Disposition","attachment; filename=va-hotel-revenue-records.csv");var w=res.getWriter();w.println("Payment ID,Reservation ID,Amount,Method,Status,Created At");for(PaymentRecord p:payments.findAll())w.printf("%d,%d,%s,%s,%s,%s%n",p.getId(),p.getReservation().getId(),p.getAmount(),p.getMethod(),p.getStatus(),p.getCreatedAt());}

 @GetMapping("/management/special-requests") public String specialRequests(Model m){m.addAttribute("reservations",reservations.findAll().stream().filter(x->x.getRequestedCheckOut()!=null||x.getRequestedUpgradeRoomId()!=null||x.isEarlyCheckoutRequested()||"PENCIL".equals(x.getBookingType())).toList());return "special-requests";}
 @PostMapping("/management/reservations/{id}/extension/{decision}") public String extension(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f,org.springframework.security.core.Authentication actor){Reservation r=reservations.findById(id).orElseThrow();if(r.getRequestedCheckOut()==null){f.addFlashAttribute("error","No extension request found.");return "redirect:/management/special-requests";}if("approve".equals(decision)){long extraNights=java.time.temporal.ChronoUnit.DAYS.between(r.getCheckOut(),r.getRequestedCheckOut());java.time.LocalDate oldOut=r.getCheckOut();boolean conflict=reservations.findAll().stream().anyMatch(other->!other.getId().equals(r.getId())&&other.getRoom().getId().equals(r.getRoom().getId())&&other.getCheckIn().isBefore(r.getRequestedCheckOut())&&other.getCheckOut().isAfter(oldOut)&&!"CANCELLED".equals(other.getStatus())&&!"REJECTED".equals(other.getStatus())&&!"CHECKED_OUT".equals(other.getStatus()));if(conflict){f.addFlashAttribute("error","The room is already reserved during the requested extension.");return "redirect:/management/special-requests";}BigDecimal revised=r.getTotalPrice().add(r.getRoom().getNightlyPrice().multiply(BigDecimal.valueOf(extraNights)));r.setCheckOut(r.getRequestedCheckOut());r.setTotalPrice(revised);r.setRequestedCheckOut(null);f.addFlashAttribute("message","Extension approved. Updated total is ₱"+revised+". Customer can pay the additional balance.");}else r.setRequestedCheckOut(null);reservations.save(r);String update="approve".equals(decision)?"Your checkout extension was approved. New checkout date: "+r.getCheckOut()+".":"Your checkout extension request was declined.";email.sendReservationUpdate(r,update);decisionLogs.record(actor,update,"Reservation #"+id,"Checkout extension; current checkout: "+r.getCheckOut());return "redirect:/management/special-requests";}
 @PostMapping("/management/reservations/{id}/early-checkout/{decision}") public String earlyCheckoutDecision(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f,org.springframework.security.core.Authentication actor){Reservation r=reservations.findById(id).orElseThrow();if(!r.isEarlyCheckoutRequested()){f.addFlashAttribute("error","No early checkout request found.");return "redirect:/management/special-requests";}if("approve".equals(decision)){r.setStatus("CHECKED_OUT");r.setCheckedOutAt(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")));}r.setEarlyCheckoutRequested(false);reservations.save(r);String update="approve".equals(decision)?"Your early checkout request was approved and the stay was checked out.":"Your early checkout request was declined.";email.sendReservationUpdate(r,update);decisionLogs.record(actor,update,"Reservation #"+id,"Early checkout decision; status: "+r.getStatus());return "redirect:/management/special-requests";}
 @PostMapping("/management/reservations/{id}/upgrade/{decision}") public String upgradeDecision(@PathVariable Long id,@PathVariable String decision,RedirectAttributes f,org.springframework.security.core.Authentication actor){Reservation r=reservations.findById(id).orElseThrow();Long targetId=r.getRequestedUpgradeRoomId();if(targetId==null){f.addFlashAttribute("error","No upgrade request found.");return "redirect:/management/special-requests";}if("approve".equals(decision)){Room target=rooms.findById(targetId).orElseThrow();if(!target.isActive()||reservations.countOverlaps(target,r.getCheckIn(),r.getCheckOut())>0){f.addFlashAttribute("error","Requested room is no longer available.");return "redirect:/management/special-requests";}long nights=java.time.temporal.ChronoUnit.DAYS.between(r.getCheckIn(),r.getCheckOut());BigDecimal revised=target.getNightlyPrice().multiply(BigDecimal.valueOf(nights));r.setRoom(target);r.setTotalPrice(revised);f.addFlashAttribute("message","Upgrade approved. Review the revised balance before collecting additional payment.");}r.setRequestedUpgradeRoomId(null);reservations.save(r);String update="approve".equals(decision)?"Your room upgrade request was approved. Updated room: "+r.getRoom().getRoomNumber()+"; updated total: PHP "+r.getTotalPrice()+".":"Your room upgrade request was declined.";email.sendReservationUpdate(r,update);decisionLogs.record(actor,update,"Reservation #"+id,"Room upgrade decision; current room: "+r.getRoom().getRoomNumber());return "redirect:/management/special-requests";}



 @PostMapping("/management/reservations/{id}/checkin") public String completeCheckin(@PathVariable Long id,RedirectAttributes f,org.springframework.security.core.Authentication actor){Reservation r=reservations.findById(id).orElseThrow();java.time.LocalDate today=java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila"));if(!"APPROVED".equals(r.getStatus())||!r.getCheckIn().equals(today)){f.addFlashAttribute("error","Check-in is allowed only for an approved reservation on its scheduled arrival date.");return "redirect:/management/history";}r.setCheckedInAt(today);r.setStatus("CHECKED_IN");reservations.save(r);email.sendReservationUpdate(r,"Check-in has been completed.");decisionLogs.record(actor,"Completed guest check-in","Reservation #"+id,"Room "+r.getRoom().getRoomNumber());f.addFlashAttribute("message","Guest checked in successfully.");return "redirect:/management/history";}
 @PostMapping("/management/reservations/{id}/checkout") public String completeCheckout(@PathVariable Long id,RedirectAttributes f,org.springframework.security.core.Authentication actor){Reservation r=reservations.findById(id).orElseThrow();if(!"CHECKED_IN".equals(r.getStatus())){f.addFlashAttribute("error","Only checked-in guests can complete checkout.");return "redirect:/management/history";}r.setStatus("CHECKED_OUT");r.setCheckedOutAt(java.time.LocalDate.now(java.time.ZoneId.of("Asia/Manila")));reservations.save(r);email.sendReservationUpdate(r,"Checkout has been completed. Thank you for staying with VA Hotel.");decisionLogs.record(actor,"Completed guest checkout","Reservation #"+id,"Room "+r.getRoom().getRoomNumber());f.addFlashAttribute("message","Checkout completed.");return "redirect:/management/history";}

}
